[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$RepositoryRoot)
$ErrorActionPreference='Stop';$r=(Resolve-Path $RepositoryRoot).Path;$ops=Join-Path $r 'docs/etc/operations';$in=Join-Path $ops 'mvdm-file-recovery-ledger.tsv';$rows=@(Import-Csv $in -Delimiter "`t"|Where-Object {$_.target_path -like 'wow32/*'}|Sort-Object target_path);if($rows.Count -ne 201){throw "Expected 201 WOW32 paths, found $($rows.Count)."}
$active=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);$disabled=$false;foreach($l in Get-Content (Join-Path $r 'src/mvdm-host/wow32/sources')){if($l -match '^!IF\s+0'){$disabled=$true;continue};if($disabled -and $l -match '^!ENDIF'){$disabled=$false;continue};if(!$disabled -and $l -match '^\s*([\w]+\.(?:c|rc))\s*\\?'){[void]$active.Add($matches[1])}}
if($active.Count -ne 78){throw "Expected 78 active WOW32 build inputs, found $($active.Count)."}
$out=foreach($x in $rows){$leaf=Split-Path $x.target_path -Leaf;if($active.Contains($leaf)){$role='historical-wow32-active-provider-body';$disp='WOW owner-package prerequisite; no body enabled';$sum='selected by original WOW32 DLL build; preserve original user/gdi/thunk/provider control flow as one package'}elseif($x.file_kind -eq 'source'){$role='historical-wow32-unselected-source';$disp='unselected source evidence only';$sum='not selected by active original WOW32 sources configuration'}elseif($x.file_kind -eq 'declaration'){$role='historical-wow32-declaration-or-table';$disp='declaration/table recovery prerequisite';$sum='original WOW32 ABI/table/layout evidence'}else{$role='historical-wow32-build-or-resource-input';$disp='build/resource evidence only';$sum='original WOW32 DLL build, export, profile or resource input'};[pscustomobject][ordered]@{file_id=$x.file_id;source_path=$x.target_path;file_kind=$x.file_kind;original_role_group=$role;provisional_component_owner='mvdm-host';required_boundary_owner='adapter-wow; adapter-win32; adapter-softpc; adapter-vdm-monitor; session';original_contract_summary=$sum;provisional_disposition=$disp;state='provisional-not-enabled';evidence="$($x.target_path); wow32/sources (condition-aware)"}}
$out|ConvertTo-Csv -NoTypeInformation -Delimiter "`t"|Set-Content (Join-Path $ops 'm0-t276-s22-wow32-file-disposition-ledger.tsv') -Encoding utf8;Write-Output "T276 S22 WOW32 disposition generated: $($out.Count) rows."
